// date_trunc PostgreSQL uyumlu interval değerleri gerektirir
// Kullanıcı dostu kısaltmaları PostgreSQL formatına çeviriyoruz
const INTERVAL_MAP: Record<string, string> = {
  '1h': 'hour',
  '1d': 'day',
  '1w': 'week',
  '1m': 'month',
};

router.get('/metrics', async (req, res) => {
  const { source, metric, from, to, interval = '1h' } = req.query;

  const pgInterval = INTERVAL_MAP[interval as string];
  if (!pgInterval) {
    return res.status(400).json({ error: `Geçersiz interval: ${interval}. Desteklenen: ${Object.keys(INTERVAL_MAP).join(', ')}` });
  }

  const result = await pool.query(`
    SELECT 
      date_trunc($1, timestamp) as bucket,
      AVG(value) as avg_value,
      MIN(value) as min_value,
      MAX(value) as max_value,
      COUNT(*) as count
    FROM metrics
    WHERE source = $2
      AND metric_name = $3
      AND timestamp BETWEEN $4 AND $5
    GROUP BY bucket
    ORDER BY bucket ASC
  `, [pgInterval, source, metric, from, to]);

  res.json(result.rows);
});

