async function seedMetrics() {
  const sources = ['web-app', 'mobile-app', 'api-gateway'];
  const metrics = ['cpu_usage', 'memory_usage', 'response_time', 'error_rate', 'request_count'];

  const now = Date.now();
  const thirtyDaysAgo = now - 30 * 24 * 60 * 60 * 1000;

  for (const source of sources) {
    for (const metric of metrics) {
      const baseValue = getBaseValue(metric); // cpu: 40-80, memory: 60-90, etc.
      for (let ts = thirtyDaysAgo; ts < now; ts += 5 * 60 * 1000) {
        // Add realistic variation: daily pattern + noise + occasional spikes
        const hourOfDay = new Date(ts).getHours();
        const dailyPattern = Math.sin((hourOfDay - 6) * Math.PI / 12) * 0.2; // Peak at noon
        const noise = (Math.random() - 0.5) * 0.1;
        const spike = Math.random() > 0.995 ? Math.random() * 0.5 : 0; // Rare spikes
        const value = baseValue * (1 + dailyPattern + noise + spike);

        await insertMetric(source, metric, value, new Date(ts));
      }
    }
  }
}

