  metricName: string, from: string, to: string
) {
  const result = await pool.query(
    `SELECT date_trunc('hour', timestamp) as bucket,
     AVG(value) as avg_value
     FROM metrics WHERE metric_name = $1
     AND timestamp BETWEEN $2 AND $3

   GROUP BY bucket ORDER BY bucket ASC`,
  [metricName, from, to]
);
const series = result.rows;
const latest = series.length > 0
  ? series[series.length - 1].avg_value : 0;
const prev = series.length > 1
  ? series[series.length - 2].avg_value : latest;

  return {
    latest, trend: latest - prev,
    status: latest > 90 ? 'critical'
      : latest > 75 ? 'warning' : 'healthy',
    series
  };
}

