// hooks/useMetrics.ts
import { useState, useEffect, useRef } from 'react';

interface UseMetricsOptions {
  source: string;
  metric: string;
  from: Date;
  to: Date;
  interval?: string;
  refreshInterval?: number;
}

export function useMetrics(options: UseMetricsOptions) {
  const [data, setData] = useState<MetricPoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const staleData = useRef<MetricPoint[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Show stale data while fetching (SWR pattern)
        if (staleData.current.length > 0) {
          setData(staleData.current);
          setLoading(false);
        }

        const params = new URLSearchParams({
          source: options.source,
          metric: options.metric,
          from: options.from.toISOString(),
          to: options.to.toISOString(),
          interval: options.interval || '1h',
        });

        const res = await fetch(`/api/metrics?${params}`);
        const json = await res.json();
        setData(json);
        staleData.current = json;
        setError(null);
      } catch (err) {
        setError(err as Error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    if (options.refreshInterval) {
      const timer = setInterval(fetchData, options.refreshInterval);
      return () => clearInterval(timer);
    }
  }, [options.source, options.metric, options.from.getTime(), options.to.getTime()]);

  return { data, loading, error };
}

